/** w = white, m = mannequin, h = AI model (human), b = all generated, o = original */
export type PhotoChoice = 'w' | 'm' | 'h' | 'b' | 'o';
type KindCode = 'w' | 'm' | 'h';
type KindStatus = 'pending' | 'done' | 'failed';

export interface StudioCandidates {
  white?: string | null;
  mannequin?: string | null;
  model?: string | null;
}

/** Display / storage order of generated photos. */
const KIND_ORDER: StudioPhotoKind[] = ['model', 'white', 'mannequin'];

interface StudioState extends StudioCandidates {
  kinds?: StudioPhotoKind[];
  status?: Partial<Record<StudioPhotoKind, KindStatus>>;
  retries?: Partial<Record<StudioPhotoKind, number>>;
  choice_msg_id?: number | null;
  /** legacy / limit marker */
  limit?: boolean;
}

export type StudioPhotoJob =
  | { type: 'draft'; sessionId: string; kind: StudioPhotoKind }
  | { type: 'product'; productId: string; chatId: string; jobId: string; kind: StudioPhotoKind };

const MAX_RETRIES_PER_KIND = 2;
const KIND_CODE: Record<StudioPhotoKind, KindCode> = { white: 'w', mannequin: 'm', model: 'h' };
const CODE_KIND: Record<KindCode, StudioPhotoKind> = { w: 'white', m: 'mannequin', h: 'model' };

