function t(key: keyof typeof T, lang: BotLang, vars: Record<string, string | number> = {}): string {
  let text: string = T[key][lang] || T[key].uz;
  for (const [k, v] of Object.entries(vars)) text = text.split(`{${k}}`).join(String(v));
  return text;
}

const escapeHtml = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const kindLabel = (kind: StudioPhotoKind, lang: BotLang) =>
  kind === 'white' ? t('kindWhite', lang) : kind === 'model' ? t('kindModel', lang) : t('kindMannequin', lang);

function choiceLabel(choice: PhotoChoice, lang: BotLang): string {
  return {
    w: t('btnWhite', lang),
    m: t('btnMannequin', lang),
    h: t('btnModel', lang),
    b: t('btnBoth', lang),
    o: t('btnOriginal', lang),
  }[choice];
}

/** Generated photos that exist, in display order. */
const readyKinds = (c: StudioCandidates): StudioPhotoKind[] => KIND_ORDER.filter((k) => Boolean(c[k]));

/** Choice keyboard; only offers options that exist. The current choice is marked with ✔️. */
function buildChoiceKeyboard(prefix: string, c: StudioCandidates, lang: BotLang, selected?: PhotoChoice): InlineKeyboard {
  const btn = (choice: PhotoChoice): InlineButton => ({
    text: `${selected === choice ? '✔️ ' : ''}${choiceLabel(choice, lang)}`,
    callback_data: `${prefix}_${choice}`,
  });
  const ready = readyKinds(c);
  const rows: InlineButton[][] = [];
  if (ready.length) rows.push(ready.map((k) => btn(KIND_CODE[k])));
  if (ready.length > 1) rows.push([btn('b')]);
  rows.push([btn('o')]);
  return { inline_keyboard: rows };
}

/** Default when the seller has not chosen: all generated photos, or the original if none. */
export function defaultPhotoChoice(c: StudioCandidates): PhotoChoice {
  const ready = readyKinds(c);
  if (ready.length > 1) return 'b';
  if (ready.length === 1) return KIND_CODE[ready[0]];
  return 'o';
}

/** Resolves a choice into the ordered list of image URLs (falls back to the original). */
export function resolveChosenImages(choice: PhotoChoice | undefined, c: StudioCandidates, original: string): string[] {
  const ch = choice || defaultPhotoChoice(c);
  const urls =
    ch === 'o' ? [original] : ch === 'b' ? readyKinds(c).map((k) => c[k]) : [c[CODE_KIND[ch as KindCode]]];
  const clean = urls.filter((u): u is string => typeof u === 'string' && u.length > 0 && !isTelegramApiUrl(u));
  return clean.length ? clean : [original];
}

function isValidChoice(choice: PhotoChoice, c: StudioCandidates): boolean {
  if (choice === 'o') return true;
  if (choice === 'b') return readyKinds(c).length > 1;
  return Boolean(c[CODE_KIND[choice]]);
}

const candidatesOf = (s: StudioCandidates | null | undefined): StudioCandidates => ({
  white: s?.white || null,
  mannequin: s?.mannequin || null,
  model: s?.model || null,
});

// ---------------------------------------------------------------------------
// Optimistic updates (two jobs may finish at the same time)
// ---------------------------------------------------------------------------

/**
 * Read-modify-write on a JSON column guarded by `updated_at`, retried on conflict.
 * Returns the new row value, or null if the row no longer exists (or mutate returned null).
 */
async function patchJsonRow<T>(
  supabase: SupabaseClient,
  table: 'telegram_sessions' | 'products',
  id: string,
  column: 'draft' | 'ai_metadata',
  mutate: (current: any, row: any) => T | null
): Promise<T | null> {
  const extra = table === 'telegram_sessions' ? ', step' : '';
  for (let attempt = 0; attempt < 5; attempt++) {
    const { data: row } = await supabase.from(table).select(`${column}, updated_at${extra}`).eq('id', id).maybeSingle();
    if (!row) return null;
    const next = mutate((row as any)[column] || {}, row);
    if (next === null) return null;
    let query = supabase
      .from(table)
      .update({ [column]: next, updated_at: new Date(Date.now() + attempt).toISOString() })
      .eq('id', id);
    query = (row as any).updated_at ? query.eq('updated_at', (row as any).updated_at) : query;
    const { data: updated } = await query.select('id');
    if (updated && updated.length > 0) return next;
    await new Promise((r) => setTimeout(r, 50 + Math.random() * 150));
  }
  console.warn(`[Studio photo] could not update ${table}.${column} for ${id} after retries`);
  return null;
}

// ---------------------------------------------------------------------------
// Starting jobs
// ---------------------------------------------------------------------------

/**
 * Starts a studio photo job in a separate serverless invocation (own time budget),
 * so the webhook can answer Telegram immediately. Falls back to running inline.
 */
export function triggerStudioPhotoJob(job: StudioPhotoJob, supabase: SupabaseClient) {
  const secret = process.env.TELEGRAM_WEBHOOK_SECRET;
  const base = (process.env.PHOTO_JOB_BASE_URL || SITE_URL).replace(/\/$/, '');

  const run = async () => {
    if (secret) {
      try {
        const res = await fetch(`${base}/api/telegram/photo-job`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'x-photo-job-secret': secret },
          body: JSON.stringify(job),
          signal: AbortSignal.timeout(10000),
        });
        if (res.ok) return;
        console.warn('[Studio photo] job route returned', res.status, '- running inline');
      } catch (err) {
        console.warn('[Studio photo] job route unreachable, running inline:', err);
      }
    }
    await runStudioPhotoJob(supabase, job);
  };

  waitUntil(run().catch((err) => console.error('[Studio photo] job failed:', err)));
}

/**
 * Which studio photo clothing gets (env AI_PHOTO_STYLE):
 *   model     – fictional AI fashion model wearing the item (default)
 *   mannequin – full-body display mannequin
 *   white     – item on a white background
 * Shoes, bags, accessories and kids' clothing always get the white background.
 */
function clothingPhotoKind(): StudioPhotoKind {
  const style = process.env.AI_PHOTO_STYLE?.trim().toLowerCase();
  return style === 'white' || style === 'mannequin' ? style : 'model';
}

function kindsFor(categoryName: string | null | undefined, gender: string | null | undefined): StudioPhotoKind[] {
  const isKids = (gender || '').toUpperCase() === 'KIDS';
  if (!isApparelCategory(categoryName) || isKids) return ['white'];
  return [clothingPhotoKind()];
}

/** Called right after a draft is created: checks the daily limit and starts one job per photo kind. */
export async function startDraftStudioPhotos(ctx: SellerContext, sessionId: string): Promise<void> {
  if (!isAiPhotoEnabled()) return;

  if (!(await hasAiPhotoQuota(ctx.store.id))) {
    await patchJsonRow(ctx.supabase, 'telegram_sessions', sessionId, 'draft', (d) => ({
      ...d,
      ai_photos: { limit: true },
    }));
    await sendTelegramMessage(ctx.chatId, t('limit', ctx.lang, { limit: getAiPhotoDailyLimit() }));
    return;
  }

  const state = await patchJsonRow(ctx.supabase, 'telegram_sessions', sessionId, 'draft', (d) => {
    const kinds = kindsFor(d.ai?.category || d.category_name, d.ai?.gender);
    const ai_photos: StudioState = {
      kinds,
      status: Object.fromEntries(kinds.map((k) => [k, 'pending'])),
      retries: {},
      choice_msg_id: null,
    };
    return { ...d, ai_photos };
  });
  if (!state) return;

  await sendTelegramMessage(ctx.chatId, t('preparing', ctx.lang));
  for (const kind of (state as any).ai_photos.kinds as StudioPhotoKind[]) {
    triggerStudioPhotoJob({ type: 'draft', sessionId, kind }, ctx.supabase);
  }
}

/** "✨ Enhance photo" for an existing product. */
export async function startProductStudioPhotos(ctx: SellerContext, productId: string, cbId: string) {
  if (!isAiPhotoEnabled()) {
    await answerTelegramCallbackQuery(cbId);
    return;
  }
  if (!(await hasAiPhotoQuota(ctx.store.id))) {
    await answerTelegramCallbackQuery(cbId, t('limit', ctx.lang, { limit: getAiPhotoDailyLimit() }), true);
    return;
  }

  const { data: product } = await ctx.supabase
    .from('products')
    .select('id, category_id, gender, ai_metadata')
    .eq('id', productId)
    .eq('store_id', ctx.store.id)
    .maybeSingle();
  if (!product) {
    await answerTelegramCallbackQuery(cbId, t('notAvailable', ctx.lang), true);
    return;
  }
  const categoryName = await productCategoryName(ctx.supabase, product);
  const kinds = kindsFor(categoryName, product.gender || product.ai_metadata?.gender);
  const jobId = crypto.randomUUID();

  await patchJsonRow(ctx.supabase, 'products', productId, 'ai_metadata', (m) => ({
    ...m,
    ai_photo_candidates: {},
    ai_photo_job: {
      id: jobId,
      kinds,
      status: Object.fromEntries(kinds.map((k) => [k, 'pending'])),
      retries: {},
      choice_msg_id: null,
    } satisfies StudioState & { id: string },
  }));

  await answerTelegramCallbackQuery(cbId);
  await sendTelegramMessage(ctx.chatId, t('preparingProduct', ctx.lang));
  for (const kind of kinds) {
    triggerStudioPhotoJob({ type: 'product', productId, chatId: ctx.chatId, jobId, kind }, ctx.supabase);
  }
}

async function productCategoryName(supabase: SupabaseClient, product: any): Promise<string | null> {
  let name: string | null = product.ai_metadata?.category || null;
  if (product.category_id) {
    const { data: cat } = await supabase.from('categories').select('name').eq('id', product.category_id).maybeSingle();
    name = cat?.name || name;
  }
  return name;
}

// ---------------------------------------------------------------------------
// Running jobs (background invocation)
// ---------------------------------------------------------------------------

async function sellerLangByChat(supabase: SupabaseClient, chatId: string): Promise<BotLang> {
  const { data: user } = await supabase.from('users').select('id').eq('telegram_id', chatId).maybeSingle();
  return user ? fetchSellerLanguage(supabase, user.id) : 'uz';
}

export async function runStudioPhotoJob(supabase: SupabaseClient, job: StudioPhotoJob): Promise<void> {
  if (job.type === 'draft') await runDraftJob(supabase, job.sessionId, job.kind);
  else await runProductJob(supabase, job.productId, job.chatId, job.jobId, job.kind);
}

async function runDraftJob(supabase: SupabaseClient, sessionId: string, kind: StudioPhotoKind) {
  const deadline = Date.now() + STUDIO_JOB_BUDGET_MS;
  const { data: session } = await supabase.from('telegram_sessions').select('*').eq('id', sessionId).maybeSingle();
  if (!session) {
    // Published already (or cancelled): the product path handles retries started from the product
    return;
  }
  const chatId: string = session.seller_telegram_id;
  const storeId: string = session.store_id;
  const lang = await sellerLangByChat(supabase, chatId);

  let photo: Awaited<ReturnType<typeof generateStudioPhoto>> | null = null;
  const source = await fetchTrustedImage(session.processed_image_url || session.draft?.image);
  if (source) {
    try {
      photo = await generateStudioPhoto({
        source,
        storeId,
        jobId: sessionId,
        kind,
        categoryName: session.draft?.ai?.category || session.draft?.category_name || null,
        gender: session.draft?.ai?.gender || null,
        deadline,
      });
    } catch (err) {
      console.warn(`[Studio photo] ${kind} failed for draft ${sessionId}:`, (err as Error).message);
    }
  }

  // Record the result in the draft (if it still exists and is not being published)
  const draft = await patchJsonRow(supabase, 'telegram_sessions', sessionId, 'draft', (d, row) => {
    if (row.step === 'PUBLISHING') return null; // publish in progress: handled via the product below
    const s: StudioState = { ...(d.ai_photos || {}) };
    s.status = { ...(s.status || {}), [kind]: photo ? 'done' : 'failed' };
    if (photo) s[kind] = photo.publicUrl;
    const next = { ...d, ai_photos: s };
    if (!d.photo_choice_by_seller) next.photo_choice = defaultPhotoChoice(candidatesOf(s));
    return next;
  });

  if (!draft) {
    // The draft was published (or is being published) meanwhile: attach the photo to the product
    for (let i = 0; i < 4; i++) {
      await new Promise((r) => setTimeout(r, 1500));
      const { data: product } = await supabase
        .from('products')
        .select('id')
        .eq('store_id', storeId)
        .eq('ai_metadata->>telegram_session_id', sessionId)
        .maybeSingle();
      if (product) {
        await recordProductResult(supabase, product.id, chatId, lang, kind, photo, sessionId);
        return;
      }
    }
    return;
  }

  const state: StudioState = (draft as any).ai_photos;
  if (photo) {
    await sendTelegramPhoto(chatId, photo.jpeg, kindLabel(kind, lang));
  } else {
    await notifyFailure(chatId, lang, kind, `aiph_r_d_${sessionId}_${KIND_CODE[kind]}`, state.retries?.[kind] || 0);
  }
  await refreshChoiceMessage(supabase, {
    chatId,
    lang,
    state,
    prefix: `aiph_d_${sessionId}`,
    selected: (draft as any).photo_choice,
    header: null,
    saveMsgId: (msgId) =>
      patchJsonRow(supabase, 'telegram_sessions', sessionId, 'draft', (d) => ({
        ...d,
        ai_photos: { ...(d.ai_photos || {}), choice_msg_id: msgId },
      })),
  });
}

async function runProductJob(
  supabase: SupabaseClient,
  productId: string,
  chatId: string,
  jobId: string,
  kind: StudioPhotoKind
) {
  const deadline = Date.now() + STUDIO_JOB_BUDGET_MS;
  const lang = await sellerLangByChat(supabase, chatId);

  // Authorize: the product must belong to the store owned by the seller linked to this chat
  const { data: user } = await supabase.from('users').select('id, role').eq('telegram_id', chatId).maybeSingle();
  if (!user || user.role !== 'SELLER') return;
  const { data: store } = await supabase.from('stores').select('id').eq('owner_id', user.id).maybeSingle();
  if (!store) return;
  const { data: product } = await supabase
    .from('products')
    .select('id, title, original_image, processed_images, category_id, gender, ai_metadata')
    .eq('id', productId)
    .eq('store_id', store.id)
    .maybeSingle();
  if (!product) return;

  const sourceUrl = product.original_image || (Array.isArray(product.processed_images) ? product.processed_images[0] : null);
  const source = await fetchTrustedImage(sourceUrl);
  if (!source) {
    await sendTelegramMessage(chatId, t('noSource', lang));
    return;
  }

  let photo: Awaited<ReturnType<typeof generateStudioPhoto>> | null = null;
  try {
    photo = await generateStudioPhoto({
      source,
      storeId: store.id,
      jobId,
      kind,
      categoryName: await productCategoryName(supabase, product),
      gender: product.gender || product.ai_metadata?.gender || null,
      deadline,
    });
  } catch (err) {
    console.warn(`[Studio photo] ${kind} failed for product ${productId}:`, (err as Error).message);
  }
  await recordProductResult(supabase, product.id, chatId, lang, kind, photo, jobId);
}

/** Saves a generated (or failed) photo on a published product and updates the seller. */
async function recordProductResult(
  supabase: SupabaseClient,
  productId: string,
  chatId: string,
  lang: BotLang,
  kind: StudioPhotoKind,
  photo: { publicUrl: string; jpeg: Buffer } | null,
  jobId: string
) {
  const meta = await patchJsonRow(supabase, 'products', productId, 'ai_metadata', (m) => {
    const job: StudioState & { id?: string } = { ...(m.ai_photo_job || {}), id: m.ai_photo_job?.id || jobId };
    job.status = { ...(job.status || {}), [kind]: photo ? 'done' : 'failed' };
    if (!job.kinds) job.kinds = [kind];
    const candidates = { ...(m.ai_photo_candidates || {}) };
    if (photo) candidates[kind] = photo.publicUrl;
    return { ...m, ai_photo_job: job, ai_photo_candidates: candidates };
  });
  if (!meta) return;

  const { data: product } = await supabase.from('products').select('title').eq('id', productId).maybeSingle();
  const job: StudioState = (meta as any).ai_photo_job;
  const state: StudioState = { ...job, ...candidatesOf((meta as any).ai_photo_candidates) };

  if (photo) await sendTelegramPhoto(chatId, photo.jpeg, kindLabel(kind, lang));
  else await notifyFailure(chatId, lang, kind, `aiph_r_p_${productId}_${KIND_CODE[kind]}`, job.retries?.[kind] || 0);

  await refreshChoiceMessage(supabase, {
    chatId,
    lang,
    state,
    prefix: `aiph_p_${productId}`,
    selected: undefined,
    header: t('readyProduct', lang, { title: escapeHtml(product?.title || '') }),
    saveMsgId: (msgId) =>
      patchJsonRow(supabase, 'products', productId, 'ai_metadata', (m) => ({
        ...m,
        ai_photo_job: { ...(m.ai_photo_job || {}), choice_msg_id: msgId },
      })),
  });
}

async function notifyFailure(chatId: string, lang: BotLang, kind: StudioPhotoKind, retryData: string, retriesUsed: number) {
  if (retriesUsed >= MAX_RETRIES_PER_KIND) {
    await sendTelegramMessage(chatId, t('kindFailedFinal', lang, { kind: kindLabel(kind, lang) }));
    return;
  }
  await sendTelegramMessage(chatId, t('kindFailed', lang, { kind: kindLabel(kind, lang) }), {
    inline_keyboard: [[{ text: t('btnRetry', lang), callback_data: retryData }]],
  });
}

/**
 * Replaces the choice message with a fresh one listing the photos ready so far.
 * Sent below the newest photo so it is always the last message; the previous one is deleted.
 */
async function refreshChoiceMessage(
  supabase: SupabaseClient,
  opts: {
    chatId: string;
    lang: BotLang;
    state: StudioState;
    prefix: string;
    selected: PhotoChoice | undefined;
    header: string | null;
    saveMsgId: (msgId: number) => Promise<unknown>;
  }
) {
  const { chatId, lang, state } = opts;
  const c = candidatesOf(state);
  if (readyKinds(c).length === 0) return;

  const kinds = state.kinds || [];
  const pending = kinds.filter((k) => state.status?.[k] === 'pending');
  const done = kinds.filter((k) => state.status?.[k] === 'done');

  let text: string;
  if (opts.header) {
    text = opts.header;
  } else if (pending.length > 0) {
    text = t('partlyReady', lang, {
      done: done.map((k) => kindLabel(k, lang)).join(', '),
      pending: pending.map((k) => kindLabel(k, lang)).join(', '),
    });
  } else {
    text = t('ready', lang);
  }
  if (opts.selected) text += `\n\n${t('chosen', lang, { choice: choiceLabel(opts.selected, lang) })}`;

  const res: any = await sendTelegramMessage(chatId, text, buildChoiceKeyboard(opts.prefix, c, lang, opts.selected));
  const newId = res?.result?.message_id;
  if (state.choice_msg_id) await deleteTelegramMessage(chatId, state.choice_msg_id);
  if (typeof newId === 'number') await opts.saveMsgId(newId);
}

// ---------------------------------------------------------------------------
// Buttons: choice and retry
// ---------------------------------------------------------------------------

interface ChoiceCallbackContext extends SellerContext {
  cbId: string;
  data: string;
  messageId?: number;
}

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';

/** Handles `aiph_*` callbacks. Returns true if handled. */
export async function handleStudioPhotoCallback(ctx: ChoiceCallbackContext): Promise<boolean> {
  const { data, cbId } = ctx;
  if (!data.startsWith('aiph_')) return false;

  const retry = data.match(new RegExp(`^aiph_r_([dp])_(${UUID})_([wmh])$`, 'i'));
  if (retry) {
    await handleRetry(ctx, retry[1] as 'd' | 'p', retry[2], CODE_KIND[retry[3] as KindCode]);
    return true;
  }

  const m = data.match(new RegExp(`^aiph_([dp])_(${UUID})_([wmhbo])$`, 'i'));
  if (!m) {
    await answerTelegramCallbackQuery(cbId);
    return true;
  }
  if (m[1] === 'd') await handleDraftChoice(ctx, m[2], m[3] as PhotoChoice);
  else await handleProductChoice(ctx, m[2], m[3] as PhotoChoice);
  return true;
}

async function handleDraftChoice(ctx: ChoiceCallbackContext, sessionId: string, choice: PhotoChoice) {
  const { supabase, chatId, store, lang, cbId } = ctx;
  const { data: owned } = await supabase
    .from('telegram_sessions')
    .select('id')
    .eq('id', sessionId)
    .eq('seller_telegram_id', chatId)
    .eq('store_id', store.id)
    .maybeSingle();
  if (!owned) {
    await answerTelegramCallbackQuery(cbId, t('draftGone', lang), true);
    return;
  }

  let invalid = false;
  const draft = await patchJsonRow(supabase, 'telegram_sessions', sessionId, 'draft', (d) => {
    if (!isValidChoice(choice, candidatesOf(d.ai_photos))) {
      invalid = true;
      return null;
    }
    return { ...d, photo_choice: choice, photo_choice_by_seller: true };
  });
  if (invalid || !draft) {
    await answerTelegramCallbackQuery(cbId, t(invalid ? 'notAvailable' : 'draftGone', lang), true);
    return;
  }

  await answerTelegramCallbackQuery(cbId, choiceLabel(choice, lang));
  if (ctx.messageId) {
    const state: StudioState = (draft as any).ai_photos || {};
    const pending = (state.kinds || []).filter((k) => state.status?.[k] === 'pending');
    const head = pending.length
      ? t('partlyReady', lang, {
          done: (state.kinds || []).filter((k) => state.status?.[k] === 'done').map((k) => kindLabel(k, lang)).join(', '),
          pending: pending.map((k) => kindLabel(k, lang)).join(', '),
        })
      : t('ready', lang);
    await editTelegramMessage(
      chatId,
      ctx.messageId,
      `${head}\n\n${t('chosen', lang, { choice: choiceLabel(choice, lang) })}`,
      buildChoiceKeyboard(`aiph_d_${sessionId}`, candidatesOf(state), lang, choice)
    );
  }
}

async function handleProductChoice(ctx: ChoiceCallbackContext, productId: string, choice: PhotoChoice) {
  const { supabase, chatId, store, lang, cbId } = ctx;
  const { data: product } = await supabase
    .from('products')
    .select('id, slug, original_image, processed_images, ai_metadata')
    .eq('id', productId)
    .eq('store_id', store.id)
    .maybeSingle();
  if (!product) {
    await answerTelegramCallbackQuery(cbId, t('notAvailable', lang), true);
    return;
  }
  const c = candidatesOf(product.ai_metadata?.ai_photo_candidates);
  if (!isValidChoice(choice, c)) {
    await answerTelegramCallbackQuery(cbId, t('notAvailable', lang), true);
    return;
  }
  const original =
    product.original_image || (Array.isArray(product.processed_images) ? product.processed_images[0] : '') || '';
  const { error } = await supabase
    .from('products')
    .update({ processed_images: resolveChosenImages(choice, c, original), updated_at: new Date().toISOString() })
    .eq('id', product.id)
    .eq('store_id', store.id);
  if (error) {
    console.error('Failed to update product photos:', error);
    await answerTelegramCallbackQuery(cbId, t('notAvailable', lang), true);
    return;
  }
  await answerTelegramCallbackQuery(cbId, choiceLabel(choice, lang));
  if (ctx.messageId) {
    await editTelegramMessage(
      chatId,
      ctx.messageId,
      t('productUpdated', lang, {
        choice: choiceLabel(choice, lang),
        url: `${SITE_URL}/product/${encodeURIComponent(product.slug)}`,
      }),
      buildChoiceKeyboard(`aiph_p_${product.id}`, c, lang, choice)
    );
  }
}

/** Retries one failed photo. Does not count against the daily limit (same product). */
async function handleRetry(ctx: ChoiceCallbackContext, scope: 'd' | 'p', id: string, kind: StudioPhotoKind) {
  const { supabase, chatId, store, lang, cbId } = ctx;
  let allowed = false;
  let exhausted = false;

  if (scope === 'd') {
    const { data: owned } = await supabase
      .from('telegram_sessions')
      .select('id')
      .eq('id', id)
      .eq('seller_telegram_id', chatId)
      .eq('store_id', store.id)
      .maybeSingle();
    if (owned) {
      await patchJsonRow(supabase, 'telegram_sessions', id, 'draft', (d) => {
        const s: StudioState = { ...(d.ai_photos || {}) };
        if (s.status?.[kind] === 'pending') return null;
        const used = s.retries?.[kind] || 0;
        if (used >= MAX_RETRIES_PER_KIND) {
          exhausted = true;
          return null;
        }
        allowed = true;
        s.retries = { ...(s.retries || {}), [kind]: used + 1 };
        s.status = { ...(s.status || {}), [kind]: 'pending' };
        if (!s.kinds?.includes(kind)) s.kinds = [...(s.kinds || []), kind];
        return { ...d, ai_photos: s };
      });
    }
  } else {
    const { data: owned } = await supabase
      .from('products')
      .select('id')
      .eq('id', id)
      .eq('store_id', store.id)
      .maybeSingle();
    if (owned) {
      let jobId = '';
      await patchJsonRow(supabase, 'products', id, 'ai_metadata', (m) => {
        const job: StudioState & { id?: string } = { ...(m.ai_photo_job || {}) };
        if (!job.id || job.status?.[kind] === 'pending') return null;
        const used = job.retries?.[kind] || 0;
        if (used >= MAX_RETRIES_PER_KIND) {
          exhausted = true;
          return null;
        }
        allowed = true;
        jobId = job.id;
        job.retries = { ...(job.retries || {}), [kind]: used + 1 };
        job.status = { ...(job.status || {}), [kind]: 'pending' };
        return { ...m, ai_photo_job: job };
      });
      if (allowed) {
        await answerTelegramCallbackQuery(cbId);
        if (ctx.messageId) await deleteTelegramMessage(chatId, ctx.messageId);
        await sendTelegramMessage(chatId, t('retrying', lang, { kind: kindLabel(kind, lang) }));
        triggerStudioPhotoJob({ type: 'product', productId: id, chatId, jobId, kind }, supabase);
        return;
      }
    }
  }

  if (!allowed) {
    await answerTelegramCallbackQuery(cbId, t(exhausted ? 'noRetries' : 'notAvailable', lang), true);
    return;
  }
  await answerTelegramCallbackQuery(cbId);
  if (ctx.messageId) await deleteTelegramMessage(chatId, ctx.messageId);
  await sendTelegramMessage(chatId, t('retrying', lang, { kind: kindLabel(kind, lang) }));
  triggerStudioPhotoJob({ type: 'draft', sessionId: id, kind }, supabase);
}
